local MournToweRewardPopUpCell = Class('MournToweRewardPopUpCell')
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournToweRewardPopUpCell:__init()
	self._questId = nil
end

function MournToweRewardPopUpCell:__delete()
	self._questId = nil
end

function MournToweRewardPopUpCell:Awake()
	--SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTeamInfo))
end

---Refresh
---@param data table
function MournToweRewardPopUpCell:Refresh(vo, isMe)
	if not vo then
		return
	end
	self.vo = vo
	self._questId = vo.id
	
	self:FillSelf()
end

function MournToweRewardPopUpCell:FillSelf()
	local t = RewardConfMgr:GetInstance():GetQuestRewardData(self._questId, Constants.QuestRewardType.FristRewards)

	UICommonUtils.FillCommonGoodsListLight(self.CommonGoodsList, t, false, false, true, false, false)
	
	local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._questId)
	if vo then
		CfUtils.FillText(self.TxtTitle, localize("第_num_层奖励", {_num_ = vo.storey}))
	end
	
	local maxTowerId = ActivityMournUtils.GetMaxPassTowerId()
	local maxVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
	
	if maxVo then
		CfUtils.SetUISwitchImage(self.ImgInk1, checkNumber(maxVo.storey) >= checkNumber(vo.storey) and 2 or 1)
		CfUtils.SetUISwitchImage(self.ImgInk2, checkNumber(maxVo.storey) >= checkNumber(vo.storey) and 2 or 1)
		
		CfUtils.SetActive(self.controller.gameObject.transform:Find("CompleteNode"), checkNumber(maxVo.storey) >= checkNumber(vo.storey))
	else
		CfUtils.SetActive(self.controller.gameObject.transform:Find("CompleteNode"), false)
	end

end

function MournToweRewardPopUpCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
	self = nil
end

return MournToweRewardPopUpCell